unsigned hits;unsigned touch(void){hits++;return 16u;}unsigned q(unsigned x,unsigned d){return x/d;}unsigned r(unsigned x,unsigned d){return x%d;}unsigned selected(unsigned x,int p){return x/(p?16u:32u);}int tested(int n){unsigned x=(unsigned)n;hits=0;volatile unsigned divisor=16u;unsigned a=x/(hits++,16u),b=x%touch(),c=x/divisor;int bad=hits!=2u;bad+=a!=(x>>4);bad+=b!=(x&15u);bad+=c!=(x>>4);bad+=q(x,10u)!=x/10u;bad+=r(x,10u)!=x%10u;bad+=selected(x,n&1)!=(x>>((n&1)?4:5));int s=n/16,t=n%16;bad+=s*16+t!=n;return bad;}